1	package com.example.starter.water.dto;
2	
3	import java.util.List;
4	
5	/**
6	 * 灌区配水 API 请求/响应契约。水量在 API 层一律使用十进制字符串（单位立方米，最多 3 位小数），
7	 * 时间使用 ISO-8601 UTC 字符串。
8	 */
9	public final class Dtos {
10	
11	    private Dtos() {
12	    }
13	
14	    /** 创建供水窗口命令。 */
15	    public record CreateWindowRequest(String commandKey, String windowKey, String channelId,
16	                                      String startUtc, String endUtc, String plannedVolume) {
17	    }
18	
19	    /** 供水窗口视图；activeCurtailmentVolume 为 null 表示无生效限供。 */
20	    public record WindowResponse(long id, String windowKey, String channelId, String startUtc, String endUtc,
21	                                 String plannedVolume, String activeCurtailmentVolume, String availableTotal,
22	                                 String createdUtc) {
23	    }
24	
25	    /** 提交配水申请命令；申请人由 X-Actor-Id 请求头提供。 */
26	    public record SubmitAllocationRequest(String commandKey, String allocationKey, Long windowId,
27	                                          String userId, String amount) {
28	    }
29	
30	    /**
31	     * 配水申请视图。状态：REQUESTED / APPROVED / CANCELLED。
32	     * amount 为不可改写的原申请水量；heldAmount 为当前持有额度（REQUESTED 为 0，普通批准时等于原水量，
33	     * 转出时等额扣减，取消时归零；持有额度恰为零的已转出申请仍为 APPROVED）。
34	     */
35	    public record AllocationResponse(String allocationKey, long windowId, String userId, String amount,
36	                                     String heldAmount, String requester, String status,
37	                                     String createdUtc, String updatedUtc) {
38	    }
39	
40	    /** 仅含幂等键的命令（批准/取消申请、取消限供）。 */
41	    public record CommandRequest(String commandKey) {
42	    }
43	
44	    /** 创建限供命令。 */
45	    public record CurtailmentRequest(String commandKey, String volume) {
46	    }
47	
48	    /** 限供视图。状态：ACTIVE / CANCELLED；cancelledUtc 未取消时为 null。 */
49	    public record CurtailmentResponse(long id, long windowId, String volume, String status,
50	                                      String createdUtc, String cancelledUtc) {
51	    }
52	
53	    /** 窗口当前可用容量视图；approvedTotal 汇总 APPROVED 申请的当前持有额度。 */
54	    public record CapacityResponse(long windowId, String plannedVolume, String activeCurtailmentVolume,
55	                                   String availableTotal, String approvedTotal, String remaining) {
