    @Test
    void transferReservesTargetHoursAndBatchRollsBackOnAnyFailure() throws Exception {
        long windowId = createAlignedWindow("ch-txhour-" + run, 1, "100");
        putCurve(windowId, caps(1, "10"), 200);
        String source = submit(windowId, "u-src", "5", 0, 1, "alice");
        approveExpect(source, 200);
        String t1 = submit(windowId, "u-t1", "2", 0, 1, "bob");
        String t2 = submit(windowId, "u-t2", "2", 0, 1, "carol");
        String t3 = submit(windowId, "u-t3", "4", 0, 1, "dave");

        // 单笔转让：目标预留 2，小时占用 5 + 2 = 7
        JsonNode tx = ok("POST", "/api/transfers", transferBody(key("tk"), source, t1), "alice");
        assertEquals(t1, tx.get("targetAllocationKey").asText());
        assertEquals("7", hourUsage(windowId, 0).get("committedVolume").asText());
        JsonNode targetNode = findAllocation(getOk("/api/windows/" + windowId + "/history"), t1);
        assertEquals("APPROVED", targetNode.get("status").asText());
        assertEquals(1, targetNode.get("approvalCurveVersion").asInt());

        // 批量转让 [2, 2]：占用 7 + 4 = 9 <= 10，整批成功
        List<Map<String, Object>> batchItems = List.of(
                Map.of("transferKey", key("tk"), "sourceAllocationKey", source, "targetAllocationKey", t2),
                Map.of("transferKey", key("tk"), "sourceAllocationKey", source, "targetAllocationKey",
                        submitExtra(windowId, "u-x", "0", 0, 1, "x")));
        // 上面第二个目标水量为 0 非法，改为直接构造 t2 + 另一笔 0.01 目标
        String t4 = submit(windowId, "u-t4", "0.01", 0, 1, "zoe");
        List<Map<String, Object>> okBatch = List.of(
                transferItem(key("tk"), source, t2),
                transferItem(key("tk"), source, t4));
        JsonNode batch = ok("POST", "/api/transfers/batch",
                Map.of("commandKey", key("tb"), "transfers", okBatch), "alice");
        assertEquals(2, batch.get("transfers").size());
        assertEquals("9.01", hourUsage(windowId, 0).get("committedVolume").asText());

        // 再批量 [4]：9.01 + 4 > 10 -> 422 整批回滚：无流水、源持有与占用不变
        JsonNode err = error("POST", "/api/transfers/batch",
                Map.of("commandKey", key("tb"), "transfers",
                        List.of(transferItem(key("tk"), source, t3))), "alice", 422);
        assertEquals("HOURLY_CAP_EXCEEDED", err.get("code").asText());
        JsonNode transfers = getOk("/api/windows/" + windowId + "/transfers").get("transfers");
        assertEquals(3, transfers.size());
        assertEquals("9.01", hourUsage(windowId, 0).get("committedVolume").asText());
        assertEquals("REQUESTED", findAllocation(getOk("/api/windows/" + windowId + "/history"), t3)
                .get("status").asText());

        // 批量内源持有不足同样整批回滚：源当前持有 5-2-2-0.01=0.99，两笔 1 各超
        String t5 = submit(windowId, "u-t5", "1", 0, 1, "erin");
        String t6 = submit(windowId, "u-t6", "1", 0, 1, "frank");
        JsonNode quotaErr = error("POST", "/api/transfers/batch",
                Map.of("commandKey", key("tb"), "transfers", List.of(
                        transferItem(key("tk"), source, t5), transferItem(key("tk"), source, t6))),
                "alice", 422);
        assertEquals("QUOTA_EXCEEDED", quotaErr.get("code").asText());
        assertEquals(1, quotaErr.get("details").get("index").asInt());
        assertEquals(3, getOk("/api/windows/" + windowId + "/transfers").get("transfers").size());
    }

    private String submitExtra(long windowId, String userId, String amount, int s, int e, String actor)
            throws Exception {
        return submit(windowId, userId, "0.01", s, e, actor);
    }

    private Map<String, Object> transferItem(String transferKey, String source, String target) {
        Map<String, Object> item = new HashMap<>();
        item.put("transferKey", transferKey);
        item.put("sourceAllocationKey", source);
        item.put("targetAllocationKey", target);
        return item;
    }

